{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE Snitch_db.maplemonk.FACT_ITEMS_SNITCH AS select a.*, case when cm.mapped_cuty is not null then upper(cm.mapped_cuty) else upper(a.city) end as city_mapped, am.sku_class, am.AVAILABLE_UNITS, uig.ageing, uig.ageing_slab, case when a.order_timestamp::date > \'2024-01-01\' then div0(a.gross_sales,a.QUANTITY)*ifnull(os.rto_quant,0) when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%rto%\' and lower(a.tags) not like \'%return%\' and lower(a.tags) not like \'%cancel%\' then ifnull(a.gross_sales,0) else 0 end as rto_sales, case when a.order_timestamp::date > \'2024-01-01\' then div0(a.gross_sales,a.QUANTITY)*ifnull(os.dto_quant,0) when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%return%\' and lower(a.tags) not like \'%rto%\' and lower(a.tags) not like \'%cancel%\' then ifnull(a.gross_sales,0) else 0 end as dto_sales, case when a.order_timestamp::date > \'2024-01-01\' then div0(a.gross_sales,a.QUANTITY)*ifnull(os.cancel_quant,0) when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%cancel%\' and lower(a.tags) not like \'%rto%\' and lower(a.tags) not like \'%return%\' then ifnull(a.gross_sales,0) else 0 end as cancel_sales, case when a.order_timestamp::date > \'2024-01-01\' then os.rto_quant when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%rto%\' and lower(a.tags) not like \'%return%\' and lower(a.tags) not like \'%cancel%\' then ifnull(a.quantity,0) else 0 end as rto_quant, case when a.order_timestamp::date > \'2024-01-01\' then os.dto_quant when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%return%\' and lower(a.tags) not like \'%cancel%\' and lower(a.tags) not like \'%rto%\' then ifnull(a.quantity,0) else 0 end as dto_quant, case when a.order_timestamp::date > \'2024-01-01\' then os.rto_initiated when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%rto%\' and lower(a.tags) not like \'%return%\' and lower(a.tags) not like \'%cancel%\' then a.order_timestamp::date end as rto_date, case when a.order_timestamp::date > \'2024-01-01\' then os.return_pickup_date when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%return%\' and lower(a.tags) not like \'%cancel%\' and lower(a.tags) not like \'%rto%\' then a.order_timestamp::date end as dto_date, case when a.order_timestamp::date > \'2024-01-01\' then os.cancel_quant when a.order_timestamp::date <= \'2024-01-01\' and a.is_refund = 1 and lower(a.tags) like \'%cancel%\' and lower(a.tags) not like \'%rto%\' and lower(a.tags) not like \'%return%\' then ifnull(a.quantity,0) else 0 end as cancel_quant, div0(discount,line_item_sales)*100 as discount_percentage, CASE WHEN discount_percentage = 0 THEN \'0\' WHEN discount_percentage < 5 THEN \'0-5\' WHEN discount_percentage < 10 THEN \'5-10\' WHEN discount_percentage < 15 THEN \'10-15\' WHEN discount_percentage < 20 THEN \'15-20\' WHEN discount_percentage < 25 THEN \'20-25\' WHEN discount_percentage < 30 THEN \'25-30\' WHEN discount_percentage < 35 THEN \'30-35\' WHEN discount_percentage < 40 THEN \'35-40\' WHEN discount_percentage < 45 THEN \'40-45\' WHEN discount_percentage < 50 THEN \'45-50\' WHEN discount_percentage < 55 THEN \'50-55\' WHEN discount_percentage < 60 THEN \'55-60\' WHEN discount_percentage < 65 THEN \'60-65\' WHEN discount_percentage < 70 THEN \'65-70\' WHEN discount_percentage < 75 THEN \'70-75\' WHEN discount_percentage < 80 THEN \'75-80\' WHEN discount_percentage < 85 THEN \'80-85\' WHEN discount_percentage < 90 THEN \'85-90\' WHEN discount_percentage < 95 THEN \'90-95\' WHEN discount_percentage < 100 THEN \'95-100\' WHEN discount_percentage = 100 THEN \'100\' WHEN discount_percentage > 100 THEN \'>100\' end as discount_slab, case when lower(city_mapped) in (\'bangalore\',\'bengaluru\',\'hyderabad\',\'delhi\',\'new delhi\',\'mumbai\',\'bombay\',\'kolkata\',\'calcutta\',\'chennai\') then \'Metro\' else \'Non-Metro\' end as Metro from ( SELECT O.SHOP_NAME, o.note, O.ORDER_ID, O.ORDER_NAME, O.CUSTOMER:id::int AS customer_id, replace(O.customer:default_address:name,\'\"\',\'\') as customer_name, O.LINE_ITEM_ID, o.app_id, coalesce(o.phone,c.phone) phone, coalesce(o.email,c.email) email, pincode, gateway, CASE WHEN gateway IN (\'cash_on_delivery\', \'Cash on Delivery (COD)\', \'Cash on Delivery\', \'cod\', \'manual\', \'partially_paid + Cash on Delivery\', \'Simpl Cash on Delivery\',\'Cash On Delivery\') THEN \'COD\' ELSE \'Prepaid\' END AS payment_channel, o.tags, case when o.order_timestamp::date >= \'2022-06-16\' and lower(o.gateway) in (\'cashfree payments\',\'cashfree\') then \'Prepaid\' when o.order_timestamp::date >= \'2022-06-16\' and lower(o.gateway) = \'\' and lower(o.tags) like \'%breeze%\' then \'Prepaid\' when o.order_timestamp::date >= \'2022-06-16\' and lower(o.gateway) like \'%cash%\' and lower(o.gateway) <> \'cashfree payments\' then \'COD\' when o.order_timestamp::date >= \'2022-06-16\' and lower(o.gateway) not like \'%cash%\' and lower(o.gateway) <> \'\' then \'Prepaid\' when o.order_timestamp::date >= \'2022-06-16\' and gateway is null and lower(pay_t.payment_type) like \'%cash%on%delivery%\' then \'COD\' when o.order_timestamp::date >= \'2022-06-16\' and lower(pay_t.payment_type) like \'%pre%paid%\' and lower(o.gateway) is null then \'Prepaid\' when o.order_timestamp::date >= \'2022-06-16\' and lower(o.gateway) not like \'%cash%\' and lower(o.gateway) = \'\' then \'Exchange\' when line_item_sales = discount then \'Exchange\' else lower(coalesce(o.payment_mode,pay_t.payment_type)) end as payment_method, case when lower(o.gateway) like \'%gokwik%\' then \'GoKwik\' when lower(o.gateway) like \'%payu%\' then \'GoKwik\' when lower(o.gateway) like \'%easebuzz%\' then \'Easebuzz\' when lower(o.gateway) like \'%cred pay%\' then \'CRED Pay\' when lower(o.gateway) like \'%snapmint%\' then \'Snapmint\' when lower(o.gateway) like \'%bharatx%\' then \'BharatPe\' when lower(o.gateway) like \'%simpl%\' then \'Simpl\' when lower(o.gateway) like \'%cashfree%\' then \'CashFree\' when lower(o.gateway) like \'%razor%\' then \'RazorPay\' when lower(o.gateway) like \'%cash%\' then \'COD\' when lower(o.gateway) like \'%axio%\' then \'Axio\' when lower(o.gateway) like \'\' then \'Exchange\' else o.gateway end as payment_gateway, case when lower(o.gateway) like \'%gokwik%\' or lower(o.tags) like \'%gokwik%\' or lower(o.note_attributes) like \'%gokwik%\' or lower(o.source_name) like \'%gokwik%\' then \'GoKwik\' when lower(o.tags) like \'%breeze%\' then \'Breeze\' when lower(o.gateway) like \'%simpl%\' or lower(o.tags) like \'%simpl%\' or lower(o.note_attributes) like \'%simpl%\' or lower(o.source_name) like \'%simpl%\' then \'Simpl\' else \'Shopify\' end as Checkout, case when lower(note_attributes) like \'%trackier%\' then 1 else 0 end as trackier_flag, case when lower(o.gateway) like \'%simple%\' then \'BNPL\' when lower(o.gateway) like \'%axio%\' then \'BNPL\' when lower(o.gateway) like \'%snapmint%\' then \'BNPL\' when lower(o.gateway) like \'%bharatx%\' then \'BNPL\' else \'Non-BNPL\' end as BNPL_flag, O.SKU, case when right(o.sku,2) = \'-S\' then left(o.sku,len(o.sku)-2) else replace(o.sku,concat(\'-\',split_part(o.sku,\'-\',-1)),\'\') end sku_group, pv.size, pv.colour, O.PRODUCT_ID, case when lower(p.tags) like \'%mad sale%\' then \'MAD Sale Collection\' when lower(p.tags) like \'%warmest winter sale%\' then \'Warmest Winter Sale Collection\' when lower(p.tags) like \'%cold%\' then \'COLD\' else \'Others\' end as Collection, CASE WHEN O.PRODUCT_NAME IS NULL THEN \'NA\' ELSE O.PRODUCT_NAME END AS PRODUCT_NAME, p.tags as product_tags, replace(p.image:src,\'\"\"\',\'\') IMAGE_lINK, O.CURRENCY, O.IS_REFUND, CASE WHEN CD.city IS NULL OR CD.city = \'\' THEN \'NA\' ELSE Cd.city END AS city, CASE WHEN CD.province IS NULL OR CD.province = \'\' THEN \'NA\' ELSE CD.province END AS state, CASE WHEN P.product_type = \'\' THEN \'NA\' WHEN P.product_type = \'Jeans\' THEN \'Denim\' WHEN P.product_type = \'Pant\' then \'Pants\' ELSE P.product_type END AS category, case when p.product_type in (\'Denim\',\'Jeans\') and lower(o.product_name) like \'%bootcut%\' then \'Bootcut Denim\' when p.product_type in (\'Denim\',\'Jeans\') and lower(o.product_name) like \'%straight fit%\' then \'Straight Fit\' when p.product_type in (\'Denim\',\'Jeans\') and (lower(product_name) not like \'%bootcut%\' and lower(product_name) not like \'%straight fit%\') then \'Other Denim\' end as Denim_type, CASE WHEN O.SKU LIKE \'%4MSQ0011%\' THEN \'LUXE\' WHEN O.SKU NOT LIKE \'%4MSQ0011%\' AND M.SKUS is NOT NULL THEN \'PLUS\' WHEN O.SKU NOT LIKE \'%4MSQ0011%\' AND N.SKUS is NOT NULL THEN \'INNERWEAR\' when P.product_type = \'Perfume & Cologne\' then \'PERFUMES\' ELSE \'OTHER\' END AS Segment, CASE WHEN O.APP_ID = \'2653365\' THEN \'Shopney\' when o.app_id = \'944701441\' then \'Appbrew\' when o.app_id = \'23414800385\' then \'Appbrew\' when o.app_id in (\'110036811777\',\'151366172673\') then \'Snitch_IOS\' ELSE \'Web\' end as WebShopney, case when p.body_html like \'%Tencil%\' then \'Tencil\' when p.body_html like \'%Rayon%\' then \'Rayon\' when p.body_html like \'%Cotton%\' then \'Cotton\' when p.body_html like \'%Polyester%\' then \'Polyester\' when p.body_html like \'%Viscose%\' then \'Viscose\' end as Material, O.order_status, O.order_timestamp, O.LINE_ITEM_SALES, O.SHIPPING_PRICE, O.QUANTITY, O.TAX, case when lower(o.tags) like \'%snitchx%\' and ifnull(O.LINE_ITEM_SALES,0) = 0 then \'YES\' else \'NO\' end as Free_gift, case when Free_gift = \'YES\' then slp.compared_price - O.LINE_ITEM_SALES end as Free_gift_discount, case when Free_gift = \'YES\' then 0 else slp.compared_price - O.LINE_ITEM_SALES end slashed_discount, O.DISCOUNT as Coupon_Discount, O.Loyalty_Discount, O.Loyalty_Customer, ifnull(o.discount,0) + ifnull(slp.compared_price - O.LINE_ITEM_SALES,0) + ifnull(Loyalty_Discount,0) as DISCOUNT, o.discount_code, o.EXCHANGE_DISCOUNT, o.discount_before_tax, O.NET_SALES - ifnull(Loyalty_Discount,0) as NET_SALES, o.total_sales - ifnull(Loyalty_Discount,0) as gross_sales, o.gross_sales_before_tax - ifnull(Loyalty_Discount,0) as gross_sales_before_tax, O.Source, O.landing_site, o.referring_site, o.payment_mode, c.return_flag, c.return_quantity, MOMENTS_COUNT, DAYSTOCONVERT, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_SOURCE, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, ShopifyQL_MAPPED_FIRSTCLICK_SOURCE, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, FINAL_UTM_SOURCE, FINAL_UTM_MEDIUM, FINAL_UTM_CAMPAIGN, Referrer_Name, GOKWIK_MAPPED_SOURCE FROM Snitch_db.maplemonk.Shopify_All_orders_items O left join (select distinct * from (select order_id ,saleorderitemcode ,phone ,email ,return_flag ,return_quantity ,row_number() over (partition by order_id, split_part(saleorderitemcode,\'-\',0) order by shipping_last_update_date desc) rw from snitch_DB.maplemonk.UNICOMMERCE_FACT_ITEMS_snitch where lower(marketplace) like any (\'%shopify%\') ) where rw=1 )c on o.order_id=c.order_id and o.line_item_id=split_part(c.saleorderitemcode,\'-\',0) LEFT JOIN (select * from Snitch_db.maplemonk.Shopify_All_products) P ON O.PRODUCT_ID = P.id LEFT JOIN ( select distinct a.sku, b.colour, c.size from snitch_db.maplemonk.shopifyindia_product_variants a left join (select id, A.value:value::string colour from snitch_db.maplemonk.shopifyindia_product_variants, lateral flatten (input => options) A where A.value:name::string in (\'Color\',\'Colour\')) b on a.id = b.id left join (select id, A.value:value::string Size from snitch_db.maplemonk.shopifyindia_product_variants, lateral flatten (input => options) A where A.value:name::string in (\'Size\')) c on a.id = c.id ) pv on pv.sku = o.sku left join snitch_db.maplemonk.snitch_plus_sku_mapping m on o.sku = m.skus left join snitch_db.maplemonk.snitch_innerwear_sku_mapping n on o.sku = n.skus LEFT JOIN(SELECT distinct customer_id, city, province, row_number() OVER ( partition BY customer_id ORDER BY id DESC) rowid FROM Snitch_db.maplemonk.Shopify_All_customers_addresses) AS CD ON O.CUSTOMER:id::int = CD.customer_id AND CD.rowid = 1 left join (select * from( select name,replace(D.value:code,\'\"\',\'\') as payment_type,row_number() over (partition by name order by 1)rw from snitch_db.maplemonk.shopifyindia_orders , lateral flatten (input =>SHIPPING_LINES,outer => true) as D ) where rw=1) pay_t on o.order_name=pay_t.name left join ( select sku_group, original_price as compared_price from snitch_db.maplemonk.correct_price) slp on lower(slp.sku_group) = lower(REVERSE(SUBSTRING(REVERSE(REPLACE(o.sku, \'\"\', \'\')), CHARINDEX(\'-\', REVERSE(REPLACE(o.sku, \'\"\', \'\'))) + 1))) ) a left join (select distinct city, mapped_cuty from snitch_db.maplemonk.snitch_city_mapping where mapped_cuty is not null) cm on a.city = cm.city left join (select distinct sku_group,sku_class,AVAILABLE_UNITS, from snitch_db.maplemonk.availability_master) am on a.sku_group = am.sku_group left join (select * from ( select \"Item Type skuCode\"as sku, \"Days in warehouse\" as ageing, *, CASE WHEN ageing < 30 THEN \'0-30\' WHEN ageing >= 30 AND ageing < 60 THEN \'30-60\' WHEN ageing >= 60 AND ageing < 90 THEN \'60-90\' WHEN ageing >= 90 AND ageing < 120 THEN \'90-120\' WHEN ageing >= 120 AND ageing < 150 THEN \'120-150\' WHEN ageing >= 150 AND ageing < 180 THEN \'150-180\' WHEN ageing >= 180 AND ageing < 210 THEN \'180-210\' WHEN ageing >= 210 AND ageing < 240 THEN \'210-240\' WHEN ageing >= 240 AND ageing < 270 THEN \'240-270\' WHEN ageing >= 270 AND ageing < 300 THEN \'270-300\' WHEN ageing >= 300 AND ageing < 330 THEN \'300-330\' WHEN ageing >= 330 AND ageing < 360 THEN \'330-360\' ELSE \'> 360\' END AS ageing_slab, row_number() over (partition by \"Item Type skuCode\" order by \"Item Created On\" desc )rw from snitch_db.maplemonk.unicommerce_inventory_aging )where rw=1) uig on a.sku = uig.sku left join (select * from (SELECT *, ROW_NUMBER() OVER (PARTITION BY line_item_id, order_name ORDER BY quantity DESC) AS row_num FROM snitch_db.maplemonk.order_status) where row_num = 1) os on a.line_item_id = os.line_item_id and a.order_name = os.order_name ;",
                    "transaction": true
                }
            ) }}
